}

facts = {
    "The capital of Gambia is Banjul.": True,
    "The capital of Nepal is Pokhara.": False,
    "The capital of Gambia is Libreville.": False,
    "The capital of Canada is Toronto.": False,
    "The capital of Iran is Tehran.": True,
    "The capital of Afghanistan is Kabul.": True,
    "The capital of Malaysia is Kuala Lumpur.": True,
    "The capital of Turkey is Istanbul.": False,
    "The capital of the Nigeria is Abuja.": True,
}

def compute(node):
    if isinstance(node, ast.Expression):
        return compute(node.body)
    if isinstance(node, ast.Constant):
        if type(node.value) is bool:
            return node.value
        if type(node.value) is int:
            return Fraction(node.value)
        raise ValueError("Unsupported constant")
    if isinstance(node, ast.UnaryOp):
        value = compute(node.operand)
        if isinstance(node.op, ast.Not):
            return not value
        if isinstance(node.op, ast.USub):
            return -value
        if isinstance(node.op, ast.UAdd):
            return value
    if isinstance(node, ast.BinOp):
        left, right = compute(node.left), compute(node.right)
        if isinstance(node.op, ast.Add):
            return left + right
        if isinstance(node.op, ast.Sub):
            return left - right
        if isinstance(node.op, ast.Mult):
            return left * right
        if isinstance(node.op, ast.Div):
            return left / right
    if isinstance(node, ast.BoolOp):
        # Evaluate every operand, rather than relying on short-circuiting.
        values = [bool(compute(value)) for value in node.values]
        if isinstance(node.op, ast.And):
            return all(values)
        if isinstance(node.op, ast.Or):
            return any(values)
    if isinstance(node, ast.Compare):
        left = compute(node.left)
        results = []
        for op, other in zip(node.ops, node.comparators):
            right = compute(other)
            if isinstance(op, ast.Gt):
                results.append(left > right)
            elif isinstance(op, ast.LtE):
                results.append(left <= right)
            else:
                raise ValueError("Unsupported comparison")
            left = right
        return all(results)
    if isinstance(node, ast.Call):
        if (isinstance(node.func, ast.Name)
                and node.func.id in ("max", "min")
                and not node.keywords):
            values = [compute(arg) for arg in node.args]
            return (max if node.func.id == "max" else min)(values)
    raise ValueError("Unsupported syntax")

try:
    values = {}
    for label, source in expressions.items():
        for sentence, truth in facts.items():
            source = source.replace(sentence, str(truth))
        source = source.replace("is less than or equal to", "<=")
        source = source.replace("is greater than", ">")
        value = compute(ast.parse(source, mode="eval"))
        if type(value) is not bool:
            raise ValueError("Expression is not Boolean")
        values[label] = value

    winners = [label for label, value in values.items() if value]
    answer = winners[0] if len(winners) == 1 else "UNSUPPORTED"
    print(json.dumps({
        "final_answer": answer,
        "evidence": {
            "values": values,
            "arithmetic": "exact rational",
            "true_count": len(winners)
        }
    }, separators=(",", ":")))
except Exception:
    print(json.dumps({"final_answer": "UNSUPPORTED"}, separators=(",", ":")))
